extra:
{
  "format": "ROUND(CAST(CASE WHEN COUNT(*) != 0 THEN COUNT(CASE WHEN in_stock_count > 0 THEN 1 ELSE NULL END) / CAST(COUNT(*) AS FLOAT) ELSE 0 END AS NUMERIC), 2)"
}

{
  "plotType": "bar",
  "dataLabels": [
    "Last Week",
    "This Week"
  ],
  "format":"COALESCE(CAST(ROUND(SUM(COALESCE(aid.week_to_date_sales, 0))) AS INTEGER), 0)::TEXT || '|' || COALESCE(CAST(ROUND(SUM(COALESCE(aid.lw_units, 0))) AS INTEGER), 0)::TEXT || ',' || COALESCE(CAST(ROUND(SUM(COALESCE(aid.week_to_date_sales, 0))) AS INTEGER), 0)::TEXT"
}

{
  "format": "ARRAY[ COALESCE(MIN(aid.tot_inv), 0), COALESCE(PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY aid.tot_inv), 0), COALESCE(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY aid.tot_inv), 0), COALESCE(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY aid.tot_inv), 0), COALESCE(MAX(aid.tot_inv), 0) ]"
}

{
  "be_configs": {
    "sql_alias": "COALESCE(SAFE_DIVIDE(SUM(wos_oh * GREATEST(oh, 0)), SUM(GREATEST(oh, 0))), 0) as wos_oh",
    "is_in_group_by_clause": false,
    "is_in_order_by_clause": false
  }
}

{
  "be_configs": {
    "sql_alias": "COALESCE(SAFE_DIVIDE(SUM(wos_oh_it * GREATEST(oh + it, 0)), SUM(GREATEST(oh + it, 0))), 0) as wos_oh_it",
    "is_in_group_by_clause": false,
    "is_in_order_by_clause": false
  }
}
